app.post('/webhooks', express.raw({ type: '*/*' }), (req, res) => {
  const digest = crypto.createHmac('sha256', process.env.SHOPIFY_API_SECRET).update(req.body).digest('base64')
  const header = req.get('X-Shopify-Hmac-SHA256') ?? ''
  const ok = header.length === digest.length && crypto.timingSafeEqual(Buffer.from(digest), Buffer.from(header))
  if (!ok) return res.sendStatus(401)
  res.sendStatus(200)
})
